/**
 * @method
 * @name interactivebrokers#signIn
 * @description obtains a live session token via the oauth 1.0a diffie-hellman exchange and opens the brokerage session, must be called prior to using other authenticated methods (called automatically by authenticate)
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/authentication/oauth-1-0-a/req-live-session-token
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} response from the exchange
 */
func (this *Interactivebrokers) SignInAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.signInBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) signInBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if *this.SafeBool(this.Options, "useGateway", false) {

		r := <-this.IbkrGatewaySignInAsync(params)
		if r.Err != nil {
			panic(r.Err)
		}
		ch <- AsyncResult[any]{Value: r.Value}
		return nil
	}
	var encryptionPemPath *string = this.SafeString(this.Options, "encryptionPemPath")
	var dhParamPemPath *string = this.SafeString(this.Options, "dhParamPemPath")
	if !(encryptionPemPath != nil && *encryptionPemPath != "") || !(dhParamPemPath != nil && *dhParamPemPath != "") {
		panic(ArgumentsRequired(this.Id + " supports two different authentication methods. You can either use the gateway or oauth 1.0 (if your account allows it) by providing encryptionPemPath and dhParamPemPath in options. Please check the FAQ for more details"))
	}
	this.IbkrCheckOauthCredentials()

	r1 := <-this.InitFileSystemAsync()
	if r1.Err != nil {
		panic(r1.Err)
	}
	var encryptionKey any = this.ReadFile(encryptionPemPath)
	var dhPrime any = this.ConvertToBigInt(Add("0x", this.ReadDhParam(dhParamPemPath)))
	// the access token secret is encrypted with the consumer's public encryption key
	var decrypted any = this.DecryptPrivateKey(encryptionKey, this.Secret)
	var accessTokenSecretHex string = this.BinaryToBase16(decrypted)
	this.Options["accessTokenSecretHex"] = accessTokenSecretHex // prepended to the signature base string in sign ()
	this.Options["serviceAccountsLoaded"] = false               // a new brokerage session needs iserver/accounts again
	var dhRandom any = this.ConvertToBigInt("0x" + this.RandomBytes(32))
	var dhChallenge any = this.ModPow(this.Options["dhGen"], dhRandom, dhPrime)
	var request map[string]any = map[string]any{
		"diffie_hellman_challenge": this.IntToBase16(dhChallenge),
	}

	r2 := <-this.WebapiPostV1ApiOauthLiveSessionToken(this.Extend(request, params))
	if r2.Err != nil {
		panic(r2.Err)
	}
	response := r2.Raw
	//
	//     {
	//         "diffie_hellman_response": "1d9c...",
	//         "live_session_token_signature": "9a7e...",
	//         "live_session_token_expiration": 1714661586311
	//     }
	//
	var dhResponse *string = this.SafeString(response, "diffie_hellman_response")
	var sharedSecret any = this.ModPow(this.ConvertToBigInt(Add("0x", dhResponse)), dhRandom, dhPrime)
	var liveSessionToken string = this.Hmac(this.Base16ToBinary(accessTokenSecretHex), this.BigToBytes(sharedSecret), sha1, "base64")
	var check string = this.Hmac(this.Encode(this.Options["consumer_key"]), this.Base64ToBinary(liveSessionToken), sha1, "hex")
	if this.SafeString(response, "live_session_token_signature") == nil || *this.SafeString(response, "live_session_token_signature") != check {
		panic(AuthenticationError(this.Id + " signIn() live session token validation failed"))
	}
	this.Options["liveSessionToken"] = liveSessionToken
	if accessed := this.SafeInteger(response, "live_session_token_expiration"); accessed != nil {
		this.Options["liveSessionTokenExpiration"] = *accessed
	} else {
		this.Options["liveSessionTokenExpiration"] = nil
	}
	// open the brokerage session
	var initRequest map[string]any
	initRequest, _ = this.Options["signInInitRequest"].(map[string]any)
	if initRequest == nil {
		initRequest = map[string]any{}
	}

	r3 := <-this.WebapiPostV1ApiIserverAuthSsodhInit(initRequest)
	if r3.Err != nil {
		panic(r3.Err)
	}

	r4 := <-this.FetchServiceAccountsAsync()
	if r4.Err != nil {
		panic(r4.Err)
	}

	ch <- AsyncResult[any]{Value: response}
	return nil
}

/**
 * @method
 * @name interactivebrokers#authenticate
 * @description signs in when there is no live session token yet or the current one is about to expire
 * @ignore
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {string} the live session token
 */
func (this *Interactivebrokers) AuthenticateAsync(optionalArgs ...any) <-chan AsyncResult[*string] {
	ch := make(chan AsyncResult[*string], 1)
	go this.authenticateBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) authenticateBody(ch chan AsyncResult[*string], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.IbkrIsAuthenticated() {

		ch <- AsyncResult[*string]{Value: this.SafeString(this.Options, "liveSessionToken")}
		return nil
	}
	// single-flight, see https://github.com/ccxt/ccxt/issues/29393
	// concurrent private calls on a cold (or expiring) instance would each pass the staleness
	// gate above and each run their own signIn (), so the first caller signs in and the rest
	// wait for it to finish, then reuse its token (or sign in themselves if the leader failed)
	if *this.SafeBool(this.Options, "signInInProgress", false) {
		var pollInterval *int64 = this.SafeInteger(this.Options, "signInPollInterval", 100)
		var maxWait *int64 = this.SafeInteger(this.Options, "signInMaxWait", 60000)
		var waited int64 = 0
		for (*this.SafeBool(this.Options, "signInInProgress", false)) && (maxWait != nil && waited < *maxWait) {

			<-this.Sleep(pollInterval)
			waited = waited + *pollInterval
		}
		if this.IbkrIsAuthenticated() {

			ch <- AsyncResult[*string]{Value: this.SafeString(this.Options, "liveSessionToken")}
			return nil
		}
	}
	this.Options["signInInProgress"] = true

	{
		func(this *Interactivebrokers) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Interactivebrokers) any {
						// catch block:
						this.Options["signInInProgress"] = false
						panic(e)

					}(this)
				}
			}()
			// try block:

			r := <-this.SignInAsync(params)
			if r.Err != nil {
				panic(r.Err)
			}
			return nil
		}(this)

	}
	this.Options["signInInProgress"] = false

	ch <- AsyncResult[*string]{Value: this.SafeString(this.Options, "liveSessionToken")}
	return nil
}

/**
 * @method
 * @name interactivebrokers#ibkrIsAuthenticated
 * @description true when the current session can be used without signing in again, with options.useGateway the gateway session was confirmed authenticated within options.gatewayAuthCheckInterval ms, otherwise the oauth live session token is fresh
 * @ignore
 * @returns {boolean} whether the current session can be used
 */
func (this *Interactivebrokers) IbkrIsAuthenticated() bool {
	if !(*this.SafeBool(this.Options, "useGateway", false)) {
		return this.IbkrHasFreshSessionToken()
	}
	var authenticatedTimestamp *int64 = this.SafeInteger(this.Options, "gatewayAuthenticatedTimestamp")
	if authenticatedTimestamp == nil {
		return false
	}
	var checkInterval int64 = *this.SafeInteger(this.Options, "gatewayAuthCheckInterval", 120000)
	return (this.Milliseconds() < (*authenticatedTimestamp + checkInterval))
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewaySignIn
 * @description checks that the client portal gateway session is authenticated (taking the brokerage session back via ssodh/init options.autoRegainSession seconds after it was lost), loads the trading accounts and starts the keep-alive loop
 * @ignore
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-brokerage-status
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} the iserver/auth/status response
 */
func (this *Interactivebrokers) IbkrGatewaySignInAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.ibkrGatewaySignInBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) ibkrGatewaySignInBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.WebapiPostV1ApiIserverAuthStatus(params)
	if r.Err != nil {
		panic(r.Err)
	}
	response := r.Raw
	//
	//     {
	//         "authenticated": true,
	//         "established": true,
	//         "competing": false,
	//         "connected": true,
	//         "message": "",
	//         "MAC": "06:A5:C8:3D:7F:EC",
	//         "serverInfo": { "serverName": "JifZ18024", "serverVersion": "Build 10.50.1e, Oct 26, 2026 5:04:19 PM" },
	//         "hardware_info": "6b0d051e|06:A5:C8:3D:7F:EC",
	//         "fail": ""
	//     }
	//
	var authenticated *bool = this.SafeBool(response, "authenticated", false)
	var established *bool = this.SafeBool(this.Options, "gatewaySessionEstablished", false)
	var openOnStart *bool = this.SafeBool(this.Options, "gatewayReauthenticate", true)
	if !(authenticated != nil && *authenticated) && !(established != nil && *established) && (openOnStart != nil && *openOnStart) {
		// the first sign in of this instance opens the brokerage session right away

		r1 := <-this.IbkrGatewayRegainSessionAsync(params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Value
		authenticated = this.SafeBool(response, "authenticated", false)
		if !(authenticated != nil && *authenticated) {
			var gatewayUrl *string = this.SafeString(this.Options, "gatewayUrl")
			panic(AuthenticationError(this.Id + " the client portal gateway session is not authenticated, log in at " + *gatewayUrl + " in a browser, " + this.Json(response)))
		}
	}
	if !(authenticated != nil && *authenticated) {
		// the sso login is alive but the brokerage session is not (e.g. taken over by a login with the same username elsewhere, or after the daily reset)
		var lostTimestamp any = this.IbkrGatewayOnSessionLost()
		var regainDelay any = this.IbkrGatewayRegainDelay()
		if IsLessThanOrEqual(regainDelay, 0) {
			var gatewayUrl *string = this.SafeString(this.Options, "gatewayUrl")
			panic(AuthenticationError(this.Id + " the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), log in again at " + *gatewayUrl + " in a browser or set options.autoRegainSession to take it back automatically, " + this.Json(response)))
		}
		var regainTimestamp any = this.Sum(lostTimestamp, regainDelay)
		if IsLessThan(this.Milliseconds(), regainTimestamp) {
			panic(AuthenticationError(Add(Add(Add(this.Id+" the brokerage session of the client portal gateway is not authenticated (e.g. it was taken over by a login with the same username elsewhere), it will be taken back at ", this.Iso8601(regainTimestamp)), " (options.autoRegainSession), "), this.Json(response))))
		}

		r2 := <-this.IbkrGatewayRegainSessionAsync(params)
		if r2.Err != nil {
			panic(r2.Err)
		}
		response = r2.Value
		authenticated = this.SafeBool(response, "authenticated", false)
		if !(authenticated != nil && *authenticated) {
			// try again options.autoRegainSession seconds later
			this.Options["gatewaySessionLostTimestamp"] = this.Milliseconds()
			this.IbkrGatewayScheduleRegain()
			panic(AuthenticationError(Add(Add(Add(this.Id+" failed to take back the brokerage session of the client portal gateway, retrying at ", this.Iso8601(this.Sum(this.Milliseconds(), regainDelay))), " (options.autoRegainSession), "), this.Json(response))))
		}
	}
	this.Options["gatewaySessionLostTimestamp"] = nil
	this.Options["serviceAccountsLoaded"] = false

	r3 := <-this.FetchServiceAccountsAsync()
	if r3.Err != nil {
		panic(r3.Err)
	}
	this.Options["gatewaySessionEstablished"] = true
	this.Options["gatewayAuthenticatedTimestamp"] = this.Milliseconds()
	this.IbkrGatewayStartKeepAlive()

	ch <- AsyncResult[any]{Value: response}
	return nil
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayRegainSession
 * @description opens the brokerage session of the client portal gateway with POST iserver/auth/ssodh/init (taking it over from any other login with the same username) and polls iserver/auth/status until it is authenticated
 * @ignore
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/initialize-session
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} the last iserver/auth/status response
 */
func (this *Interactivebrokers) IbkrGatewayRegainSessionAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.ibkrGatewayRegainSessionBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) ibkrGatewayRegainSessionBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var initRequest map[string]any
	initRequest, _ = this.Options["signInInitRequest"].(map[string]any)
	if initRequest == nil {
		initRequest = map[string]any{}
	}

	r := <-this.WebapiPostV1ApiIserverAuthSsodhInit(initRequest)
	if r.Err != nil {
		panic(r.Err)
	}
	var retries int64 = *this.SafeInteger(this.Options, "gatewayReauthenticateRetries", 5)
	var retryDelay *int64 = this.SafeInteger(this.Options, "gatewayReauthenticateDelay", 1000)
	var response any = map[string]any{}
	for i := 0; int64(i) < retries; i++ {

		<-this.Sleep(retryDelay)

		r1 := <-this.WebapiPostV1ApiIserverAuthStatus(params)
		if r1.Err != nil {
			panic(r1.Err)
		}
		response = r1.Raw
		if *this.SafeBool(response, "authenticated", false) {
			break
		}
	}

	ch <- AsyncResult[any]{Value: response}
	return nil
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayRegainDelay
 * @description options.autoRegainSession in milliseconds, 0 when the lost brokerage session must not be taken back
 * @ignore
 * @returns {int} the delay in milliseconds
 */
func (this *Interactivebrokers) IbkrGatewayRegainDelay() any {
	var seconds *float64 = this.SafeNumber(this.Options, "autoRegainSession", 0)
	if (seconds == nil) || (!(*seconds > 0)) {
		return 0
	}
	return this.ParseToInt(*seconds * 1000)
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayOnSessionLost
 * @description marks the brokerage session as lost and schedules taking it back, see options.autoRegainSession
 * @ignore
 * @returns {int} the timestamp when the session was found lost
 */
func (this *Interactivebrokers) IbkrGatewayOnSessionLost() any {
	this.Options["gatewayAuthenticatedTimestamp"] = nil
	var lostTimestamp any
	if derefPtr := this.SafeInteger(this.Options, "gatewaySessionLostTimestamp"); derefPtr != nil {
		lostTimestamp = *derefPtr
	}
	if lostTimestamp == nil {
		lostTimestamp = this.Milliseconds()
		this.Options["gatewaySessionLostTimestamp"] = lostTimestamp
		this.IbkrGatewayScheduleRegain()
	}
	return lostTimestamp
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayScheduleRegain
 * @description schedules taking the lost brokerage session back options.autoRegainSession seconds after it was lost, so it is regained even when no private calls are made, the synchronous python and php versions take it back on the next private call instead
 * @ignore
 * @returns {boolean} true if it was scheduled
 */
func (this *Interactivebrokers) IbkrGatewayScheduleRegain() any {
	var regainDelay any = this.IbkrGatewayRegainDelay()
	if (IsLessThanOrEqual(regainDelay, 0)) || (*this.SafeBool(this.Options, "gatewayRegainScheduled", false)) {
		return false
	}
	var lostTimestamp *int64 = this.SafeInteger(this.Options, "gatewaySessionLostTimestamp", this.Milliseconds())
	var wait any = Subtract(this.Sum(lostTimestamp, regainDelay), this.Milliseconds())
	if IsLessThanOrEqual(wait, 0) {
		wait = regainDelay
	}

	{
		func(this *Interactivebrokers) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Interactivebrokers) any {
						// catch block:
						this.Options["gatewayRegainScheduled"] = false
						return false

					}(this)
				}
			}()
			// try block:
			this.Delay(wait, this.IbkrGatewayRegainLoopAsync)
			this.Options["gatewayRegainScheduled"] = true
			return nil
		}(this)

	}
	return true
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayRegainLoop
 * @description takes the lost brokerage session back, rescheduled every options.autoRegainSession seconds until it succeeds, stops when it is set to 0 or the instance is closed
 * @ignore
 * @returns {undefined}
 */
func (this *Interactivebrokers) IbkrGatewayRegainLoopAsync() <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.ibkrGatewayRegainLoopBody(ch)
	return ch
}
func (this *Interactivebrokers) ibkrGatewayRegainLoopBody(ch chan AsyncResult[any]) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	this.Options["gatewayRegainScheduled"] = false
	var useGateway *bool = this.SafeBool(this.Options, "useGateway", false)
	var lostTimestamp *int64 = this.SafeInteger(this.Options, "gatewaySessionLostTimestamp")
	if !(useGateway != nil && *useGateway) || (lostTimestamp == nil) || (IsLessThanOrEqual(this.IbkrGatewayRegainDelay(), 0)) {

		ch <- AsyncResult[any]{Value: nil} // already regained, or disabled
		return nil
	}

	{
		func(this *Interactivebrokers) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Interactivebrokers) any {
						// catch block:
						if IsInstance(e, ExchangeClosedByUser) {

							return nil
						}
						if this.Verbose {
							this.Log("ibkrGatewayRegainLoop failed " + this.ExceptionMessage(e))
						}
						// e.g. the sso login is lost too (http 401), retry until it is logged in again at options.gatewayUrl
						if this.SafeInteger(this.Options, "gatewaySessionLostTimestamp") != nil {
							this.IbkrGatewayScheduleRegain()
						}
						return nil
					}(this)
				}
			}()
			// try block:

			r := <-this.AuthenticateAsync()
			if r.Err != nil {
				panic(r.Err)
			}
			return nil
		}(this)

	}

	return nil
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayStartKeepAlive
 * @description schedules the keep-alive loop once, see options.gatewayKeepAlive
 * @ignore
 * @returns {boolean} true if the loop is running
 */
func (this *Interactivebrokers) IbkrGatewayStartKeepAlive() any {
	var keepAlive *bool = this.SafeBool(this.Options, "gatewayKeepAlive", true)
	if !(keepAlive != nil && *keepAlive) || (*this.SafeBool(this.Options, "gatewayKeepAliveStarted", false)) {
		return keepAlive
	}
	var interval *int64 = this.SafeInteger(this.Options, "gatewayKeepAliveInterval", 60000)

	{
		func(this *Interactivebrokers) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Interactivebrokers) any {
						// catch block:
						// the synchronous python and php versions have no event loop to schedule on, the session is
						// then kept alive by the private calls, which re-check iserver/auth/status every gatewayAuthCheckInterval ms
						this.Options["gatewayKeepAliveStarted"] = false
						return false

					}(this)
				}
			}()
			// try block:
			this.Delay(interval, this.IbkrGatewayKeepAliveAsync)
			this.Options["gatewayKeepAliveStarted"] = true
			return nil
		}(this)

	}
	return true
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayKeepAlive
 * @description keeps the client portal gateway session alive with POST /tickle every options.gatewayKeepAliveInterval ms and tracks its authentication status, stops when options.gatewayKeepAlive is set to false or the instance is closed
 * @ignore
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-session/get-session-token
 * @returns {undefined}
 */
func (this *Interactivebrokers) IbkrGatewayKeepAliveAsync() <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.ibkrGatewayKeepAliveBody(ch)
	return ch
}
func (this *Interactivebrokers) ibkrGatewayKeepAliveBody(ch chan AsyncResult[any]) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var useGateway *bool = this.SafeBool(this.Options, "useGateway", false)
	var keepAlive *bool = this.SafeBool(this.Options, "gatewayKeepAlive", true)
	if !(useGateway != nil && *useGateway) || !(keepAlive != nil && *keepAlive) {
		this.Options["gatewayKeepAliveStarted"] = false

		return nil
	}

	{
		func(this *Interactivebrokers) (ret_ any) {
			defer func() {
				if e := recover(); e != nil {
					if e == "break" {
						return
					}
					ret_ = func(this *Interactivebrokers) any {
						// catch block:
						if IsInstance(e, ExchangeClosedByUser) {
							this.Options["gatewayKeepAliveStarted"] = false

							return nil
						}
						// a failing tickle (e.g. the gateway container restarts) is retried on the next interval
						this.Options["gatewayAuthenticatedTimestamp"] = nil
						if this.Verbose {
							this.Log("ibkrGatewayKeepAlive tickle failed " + this.ExceptionMessage(e))
						}
						return nil
					}(this)
				}
			}()
			// try block:

			r := <-this.WebapiPostV1ApiTickle()
			if r.Err != nil {
				panic(r.Err)
			}
			var response map[string]any = r.Value
			//
			//     {
			//         "session": "dcbd01d969bfd9434139f372edc338b2",
			//         "ssoExpires": 237821,
			//         "collission": false,
			//         "userId": 46130428,
			//         "hmds": { "error": "no bridge" },
			//         "iserver": { "authStatus": { "authenticated": true, "established": true, "competing": false, "connected": true, ... } }
			//     }
			//
			var iserver, _ = response["iserver"].(map[string]any)
			var authStatus, _ = iserver["authStatus"].(map[string]any)
			if *this.SafeBool(authStatus, "authenticated", false) {
				if this.SafeInteger(this.Options, "gatewaySessionLostTimestamp") == nil {
					this.Options["gatewayAuthenticatedTimestamp"] = this.Milliseconds()
				}
			} else {
				// e.g. taken over by a login with the same username elsewhere, see options.autoRegainSession
				this.IbkrGatewayOnSessionLost()
			}
			return nil
		}(this)

	}
	var interval *int64 = this.SafeInteger(this.Options, "gatewayKeepAliveInterval", 60000)
	this.Delay(interval, this.IbkrGatewayKeepAliveAsync)

	return nil
}

/**
 * @method
 * @name interactivebrokers#ibkrHasFreshSessionToken
 * @description true when a live session token is set and is not about to expire
 * @ignore
 * @returns {boolean} whether the current live session token can be used
 */
func (this *Interactivebrokers) IbkrHasFreshSessionToken() bool {
	var liveSessionToken *string = this.SafeString(this.Options, "liveSessionToken")
	if liveSessionToken == nil {
		return false
	}
	var expiration *int64 = this.SafeInteger(this.Options, "liveSessionTokenExpiration")
	if expiration == nil {
		return true
	}
	var refreshMargin int64 = *this.SafeInteger(this.Options, "liveSessionTokenRefreshMargin", 60000)
	return ((this.Milliseconds() + refreshMargin) < *expiration)
}

/**
 * @method
 * @name interactivebrokers#loadAccountId
 * @description returns the account id from params, options, or the first account returned by fetchAccounts
 * @ignore
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.accountId] the account id to use
 * @returns {Array} the account id and the params without accountId
 */
func (this *Interactivebrokers) LoadAccountIdAsync(optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.loadAccountIdBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) loadAccountIdBody(ch chan AsyncResult[any], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	accountIdFromParams, query := this.HandleOptionAndParams(params, "loadAccountId", "accountId")
	var accountId any = accountIdFromParams
	if accountId == nil {

		r := <-this.FetchAccountsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
		if derefPtr := this.SafeString(this.Options, "accountId"); derefPtr != nil {
			accountId = *derefPtr
		} else {
			accountId = nil
		}
	}
	if accountId == nil {
		panic(ArgumentsRequired(this.Id + " requires an accountId in params[\"accountId\"] or options[\"accountId\"], fetchAccounts() returned no accounts"))
	}

	ch <- AsyncResult[any]{Value: []any{accountId, query}}
	return nil
}

/**
 * @method
 * @name interactivebrokers#fetchBalance
 * @description query for balance and get the amount of funds available for trading or funds locked in orders, the cash comes from the ledger, the crypto holdings from the positions and the locked ('used') amounts from the open orders of the current brokerage session
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-portfolio-ledger
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-uncached-positions
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/get-open-orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.accountId] the account id, defaults to options["accountId"] or the selected account
 * @param {boolean} [params.positions] add the holdings of options.fetchBalance.positionAssetClasses (crypto by default) as balances, default true
 * @param {boolean} [params.openOrders] compute the locked ('used') amounts from the open orders, default true
 * @returns {object} a [balance structure]{@link https://docs.ccxt.com/?id=balance-structure}
 */
func (this *Interactivebrokers) FetchBalanceAsync(optionalArgs ...any) <-chan AsyncResult[Balances] {
	ch := make(chan AsyncResult[Balances], 1)
	go this.fetchBalanceBody(ch, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) fetchBalanceBody(ch chan AsyncResult[Balances], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	r1 := <-this.LoadAccountIdAsync(params)
	if r1.Err != nil {
		panic(r1.Err)
	}
	accountIdaccountQueryVariable := r1.Value
	accountId := GetValue(accountIdaccountQueryVariable, 0)
	accountQuery := GetValue(accountIdaccountQueryVariable, 1)
	withPositions, positionsQuery := this.HandleOptionAndParams(accountQuery, "fetchBalance", "positions", true)
	withOpenOrders, query := this.HandleOptionAndParams(positionsQuery, "fetchBalance", "openOrders", true)
	var request map[string]any = map[string]any{
		"accountId": accountId,
	}
	if EvalTruthy(withPositions) || EvalTruthy(withOpenOrders) {
		// the conids of the positions and orders are resolved to currencies via the markets
		if this.Markets == nil {

			r2 := <-this.LoadMarketsAsync()
			if r2.Err != nil {
				panic(r2.Err)
			}
		}
	}
	var promises []any = []any{}
	promises = append(promises, this.WebapiGetV1ApiPortfolioAccountIdLedger(this.Extend(request, query)))
	if EvalTruthy(withPositions) {
		promises = append(promises, this.WebapiGetV1ApiPortfolio2AccountIdPositions(request))
	}
	if EvalTruthy(withOpenOrders) {
		promises = append(promises, this.FetchLiveOrdersRawAsync())
	}

	r3 := <-promiseAll(promises)
	if r3.Err != nil {
		panic(r3.Err)
	}
	var results []any = r3.Value
	var response map[string]any = this.SafeDictMap(results, 0, map[string]any{})
	//
	//     {
	//         "USD": {
	//             "commoditymarketvalue": 0.0,
	//             "futuremarketvalue": 0.0,
	//             "settledcash": 214716688.0,
	//             "exchangerate": 1,
	//             "sessionid": 1,
	//             "cashbalance": 214716688.0,
	//             "corporatebondsmarketvalue": 0.0,
	//             "netliquidationvalue": 215335840.0,
	//             "interest": 305569.94,
	//             "unrealizedpnl": 39695.82,
	//             "stockmarketvalue": 314123.88,
	//             "currency": "USD",
	//             "realizedpnl": 0.0,
	//             "acctcode": "U1234567",
	//             "key": "LedgerList",
	//             "timestamp": 1702582321,
	//             "secondkey": "USD",
	//             ...
	//         },
	//         "BASE": { ... }
	//     }
	//
	var balanceResponse map[string]any = map[string]any{
		"ledger": response,
	}
	var index int = 1
	if EvalTruthy(withPositions) {
		balanceResponse["positions"] = this.SafeList(results, index)
		index = index + 1
	}
	if EvalTruthy(withOpenOrders) {
		// the 'orders' key is present only when the open orders were fetched, then the currencies without open orders get used = 0
		balanceResponse["orders"] = this.SafeList(results, index)
	}

	ch <- AsyncResult[Balances]{Value: BalancesFromMap(this.ParseBalance(balanceResponse))}
	return nil
}
func (this *Interactivebrokers) ParseBalance(response map[string]any) map[string]any {
	//
	//     {
	//         "ledger": { "USD": { "cashbalance": 1000.0, ... }, "BASE": { "timestamp": 1702582321, ... } },
	//         "positions": [ { "position": 0.04, "conid": "495759171", "description": "ETH CRYPTO", "secType": "CRYPTO", ... } ],
	//         "orders": [ { "conid": 479624278, "side": "BUY", "status": "Submitted", "price": "80000", "remainingQuantity": 0.001, "cashCcy": "USD", ... } ]
	//     }
	//
	var ledger map[string]any = this.SafeDictMap(response, "ledger", response)
	var positions []any = SafeListTyped(response, "positions")
	var orders []map[string]any = this.SafeListMapsTyped(response, "orders")
	var result map[string]any = map[string]any{
		"info": response,
	}
	// cash, from the ledger
	var currencyIds []string = nil
	if ledger != nil {
		currencyIds = make([]string, 0, len(ledger))
		for objectKey := range ledger {
			currencyIds = append(currencyIds, objectKey)
		}
	}
	for i := 0; i < len(currencyIds); i++ {
		var currencyId string = currencyIds[i]
		if currencyId == "BASE" {
			continue
		}
		var balance, _ = ledger[currencyId].(map[string]any)
		if balance == nil {
			continue
		}
		var code *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["total"] = this.SafeString(balance, "cashbalance")
		if code != nil {
			result[*code] = account
		}
	}
	// holdings, from the positions
	var balanceOptions, _ = this.Options["fetchBalance"].(map[string]any)
	var positionAssetClasses []any = this.SafeListSlice(balanceOptions, "positionAssetClasses", []any{"CRYPTO"})
	for i := 0; i < len(positions); i++ {
		var position any = positions[i]
		// portfolio2 positions have "secType", the cached portfolio positions have "assetClass"
		var assetClass *string = this.SafeString2(position, "secType", "assetClass")
		if !this.InArray(assetClass, positionAssetClasses) {
			continue
		}
		var code any = this.IbkrBalanceCode(position)
		if (IsEqual(code, nil)) || (InOp(result, code)) {
			continue
		}
		var account map[string]any = this.Account()
		account["total"] = this.SafeString(position, "position")
		AddElementToObject(result, code, account)
	}
	// locked amounts, from the open orders: buy orders lock remaining * price of the quote currency, sell orders lock the remaining base amount
	var used map[string]any = map[string]any{}
	for i := 0; i < len(orders); i++ {
		var order map[string]any = orders[i]
		var status *string = this.ParseOrderStatus(this.SafeString2(order, "status", "order_status"))
		if status == nil || *status != "open" {
			continue
		}
		var marketId *string = this.SafeString(order, "conid")
		var market map[string]any = this.SafeMarket(marketId)
		if *this.SafeBool(market, "contract", false) {
			continue
		}
		var remaining *string = this.SafeString2(order, "remainingQuantity", "size")
		if (remaining == nil) || !Precise.StringGt(remaining, "0") {
			continue
		}
		var side *string = this.SafeStringUpper(order, "side")
		var code any = nil
		var amount *string = nil
		if (side != nil && *side == "BUY") || (side != nil && *side == "B") {
			var price *string = this.OmitZero(this.SafeString2(order, "price", "limit_price"))
			if price == nil {
				continue
			}
			var cashCurrencyId *string = this.SafeString(order, "cashCcy")
			if cashCurrencyId != nil {
				code = this.SafeCurrencyCode(cashCurrencyId)
			} else {
				code = this.SafeString(market, "quote")
			}
			amount = Precise.StringMul(remaining, price)
		} else if (side != nil && *side == "SELL") || (side != nil && *side == "S") {
			code = this.SafeString(market, "base")
			amount = remaining
		}
		if (IsEqual(code, nil)) || !(InOp(result, code)) {
			continue
		}
		var previous *string = this.SafeString(used, code, "0")
		AddElementToObject(used, code, Precise.StringAdd(previous, amount))
	}
	var usedCodes []string = nil
	if used != nil {
		usedCodes = make([]string, 0, len(used))
		for objectKey := range used {
			usedCodes = append(usedCodes, objectKey)
		}
	}
	for i := 0; i < len(usedCodes); i++ {
		var code string = usedCodes[i]
		AddElementToObject(result[code], "used", used[code])
	}
	// every currency of the ledger and the positions gets a 'used' when the open orders were fetched, so that 'free' is computed
	if _, ok := response["orders"]; ok {
		var codes []string = nil
		if result != nil {
			codes = make([]string, 0, len(result))
			for objectKey := range result {
				codes = append(codes, objectKey)
			}
		}
		for i := 0; i < len(codes); i++ {
			var code string = codes[i]
			if (code != "info") && (this.SafeString(result[code], "used") == nil) {
				AddElementToObject(result[code], "used", "0")
			}
		}
	}
	var timestamp *int64 = this.SafeTimestamp(this.SafeDict(ledger, "BASE", map[string]any{}), "timestamp")
	result["timestamp"] = timestamp
	result["datetime"] = this.Iso8601(timestamp)
	return this.SafeBalance(result).(map[string]any)
}

/**
 * @method
 * @name interactivebrokers#ibkrBalanceCode
 * @description resolves the currency code of a position held as a balance, BTC for the BTC crypto, AAPL for the AAPL shares
 * @ignore
 * @param {object} position a raw position from portfolio2/{accountId}/positions
 * @returns {string|undefined} the currency code
 */
func (this *Interactivebrokers) IbkrBalanceCode(position any) any {
	var marketId *string = this.SafeString(position, "conid")
	var market MarketInterface = MarketInterfaceFromMap(this.SafeMarket(marketId))
	var base *string
	if market.BaseCurrency != "" {
		base = &market.BaseCurrency
	}
	if base != nil {
		return base
	}
	var description *string = this.SafeString2(position, "ticker", "description")
	if description == nil {
		return nil
	}
	var assetClass *string = this.SafeString2(position, "secType", "assetClass")
	var parts []string = strings.Split(*description, " ")
	if assetClass != nil && *assetClass == "CRYPTO" {
		// "ETH CRYPTO" -> ETH
		return this.SafeCurrencyCode(parts[0])
	}
	return strings.Join(parts, ".") // 'BRK B' -> 'BRK.B', as in parseMarket
}

/**
 * @method
 * @name interactivebrokers#beforeClose
 * @description stops the client portal gateway keep-alive and session-regain loops when close () is called, otherwise the scheduled tickles keep the event loop alive after close ()
 * @ignore
 * @returns {undefined}
 */
func (this *Interactivebrokers) BeforeClose() any {
	this.Options["gatewayKeepAlive"] = false
	this.Options["autoRegainSession"] = 0
	return nil
}
