func (this *Interactivebrokers) IbkrParseValue(value *string) any {
	// snapshot values are formatted strings: "C82838.50" (prior close), "H1.2" (halted), "+1.04", "1.5%", "1M", "1,234", "$11,000K" (bond sizes, the principal amount)
	if (value == nil) || (value != nil && *value == "") || (value != nil && *value == "N/A") {
		return nil
	}
	var valueParts []string = strings.Split(*value, ",")
	var result any = strings.Join(valueParts, "")
	if StartsWith(result, "C") || StartsWith(result, "H") || StartsWith(result, "+") || StartsWith(result, "$") {
		result = Slice(result, 1, nil)
	}
	if EndsWith(result, "%") {
		result = Slice(result, 0, GetLength(result)-1)
	}
	var multiplier *string = nil
	if EndsWith(result, "K") {
		multiplierStr := "1000"
		multiplier = &multiplierStr
	} else if EndsWith(result, "M") {
		multiplierStr2 := "1000000"
		multiplier = &multiplierStr2
	} else if EndsWith(result, "B") {
		multiplierStr3 := "1000000000"
		multiplier = &multiplierStr3
	}
	if multiplier != nil {
		var scaled *string = Precise.StringMul(Slice(result, 0, GetLength(result)-1), multiplier)
		if scaled == nil {
			return nil
		}
		result = scaled
	}
	if IsEqual(result, "") {
		return nil
	}
	return result
}
func (this *Interactivebrokers) ParseTicker(ticker any, optionalArgs ...any) Ticker {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(ticker, "conid")
	var resolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeInteger(ticker, "_updated")
	var last any = this.IbkrParseValue(this.SafeString(ticker, "7296")) // 31 might contain symbol
	if last == nil {
		// if precise fields are not provided, use generic "last price" field
		last = this.IbkrParseValue(this.SafeString(ticker, "31"))
	}
	return this.SafeTicker(map[string]any{
		"symbol":        resolved["symbol"],
		"timestamp":     timestamp,
		"datetime":      this.Iso8601(timestamp),
		"high":          this.IbkrParseValue(this.SafeString(ticker, "70")),
		"low":           this.IbkrParseValue(this.SafeString(ticker, "71")),
		"bid":           this.IbkrParseValue(this.SafeString(ticker, "84")),
		"bidVolume":     this.IbkrParseValue(this.SafeString(ticker, "88")),
		"ask":           this.IbkrParseValue(this.SafeString(ticker, "86")),
		"askVolume":     this.IbkrParseValue(this.SafeString(ticker, "85")),
		"vwap":          nil,
		"open":          this.IbkrParseValue(this.SafeString(ticker, "7295")),
		"close":         last,
		"last":          last,
		"previousClose": this.IbkrParseValue(this.SafeString(ticker, "7741")),
		"change":        this.IbkrParseValue(this.SafeString(ticker, "82")),
		"percentage":    this.IbkrParseValue(this.SafeString(ticker, "83")),
		"average":       nil,
		"baseVolume":    this.IbkrParseValue(this.SafeString(ticker, "7762")),
		"quoteVolume":   nil,
		"markPrice":     this.IbkrParseValue(this.SafeString(ticker, "7635")),
		"indexPrice":    nil,
		"info":          ticker,
	}, resolved)
}

