/**
 * @method
 * @name interactivebrokers#createOrder
 * @description create a trade order, order reply prompts are confirmed automatically when options.createOrder.autoConfirmOrderReplies is true
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/submit-new-order
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-orders/confirm-order-reply
 * @param {string} symbol unified symbol of the market to create an order in
 * @param {string} type 'market' or 'limit'
 * @param {string} side 'buy' or 'sell'
 * @param {float} amount how much of currency you want to trade in units of base currency
 * @param {float} [price] the price at which the order is to be fulfilled, in units of the quote currency, ignored in market orders
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {float} [params.triggerPrice] the stop price, creates a STP (market) or STP LMT (limit) order
 * @param {float} [params.trailingAmount] the trailing offset in quote currency, creates a TRAIL or TRAILLMT order
 * @param {float} [params.trailingPercent] the trailing offset in percent, creates a TRAIL or TRAILLMT order
 * @param {string} [params.timeInForce] 'DAY', 'IOC', 'GTC', 'OPG' or 'PAX'
 * @param {string} [params.clientOrderId] a unique id for the order, sent as cOID
 * @param {boolean} [params.outsideRTH] allow the order to execute outside regular trading hours
 * @param {string} [params.accountId] the account id, defaults to options["accountId"]
 * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
 */
func (this *Interactivebrokers) CreateOrderAsync(symbol string, typeVar string, side string, amount any, optionalArgs ...any) <-chan AsyncResult[Order] {
	ch := make(chan AsyncResult[Order], 1)
	go this.createOrderBody(ch, symbol, typeVar, side, amount, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) createOrderBody(ch chan AsyncResult[Order], symbol string, typeVar string, side string, amount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var price *float64 = GetArgFloat64Ptr(optionalArgs, 0, nil)
	_ = price
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	r2 := <-this.LoadAccountIdAsync(params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	accountIdparamsWithoutAccoundIdVariable := r2.Value
	accountId := GetValue(accountIdparamsWithoutAccoundIdVariable, 0)
	paramsWithoutAccoundId := GetValue(accountIdparamsWithoutAccoundIdVariable, 1)
	var orderRequest map[string]any = this.CreateOrderRequest(symbol, typeVar, side, amount, price, paramsWithoutAccoundId)
	orderRequest["acctId"] = accountId
	var request map[string]any = map[string]any{
		"accountId": accountId,
		"orders":    []any{orderRequest},
	}

	r3 := <-this.WebapiPostV1ApiIserverAccountAccountIdOrders(request)
	if r3.Err != nil {
		panic(r3.Err)
	}
	response := r3.Value

	r4 := <-this.IbkrHandleOrderRepliesAsync(response, "createOrder")
	if r4.Err != nil {
		panic(r4.Err)
	}
	result := r4.Value

	//
	//     [ { "order_id": "1370093239", "order_status": "PreSubmitted", "encrypt_message": "1" } ]
	//
	ch <- AsyncResult[Order]{Value: this.ParseOrder(result, market)}
	return nil
}
