func (this *Interactivebrokers) fetchCanceledAndClosedOrdersBody(ch chan AsyncResult[[]Order], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = nil
	if symbol != nil {
		market = this.Market(symbol)
	}

	r2 := <-this.FetchLiveOrdersRawAsync(params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	orders := r2.Value
	var parsed []any = ArrayTyped(this.ParseOrders(orders, market, nil, nil))
	var result []any = []any{}
	for i := 0; i < len(parsed); i++ {
		var order any = parsed[i]
		var status *string = SafeStringPtr(GetValue(order, "status"))
		if (status != nil && *status == "closed") || (status != nil && *status == "canceled") {
			result = append(result, order)
		}
	}

	ch <- AsyncResult[[]Order]{Value: OrdersFromList(this.FilterBySymbolSinceLimit(result, symbol, since, limit))}
	return nil
}

