/**
 * @method
 * @name interactivebrokers#fetchPositionsForSymbol
 * @description fetch the open positions of a single market
 * @see https://www.interactivebrokers.com/docs/web-api/api-reference/trading/trading-portfolio/get-position-by-conid
 * @param {string} symbol unified market symbol
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.accountId] the account id, defaults to options["accountId"]
 * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
 */
func (this *Interactivebrokers) FetchPositionsForSymbolAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]Position] {
	ch := make(chan AsyncResult[[]Position], 1)
	go this.fetchPositionsForSymbolBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) fetchPositionsForSymbolBody(ch chan AsyncResult[[]Position], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	r := <-this.AuthenticateAsync()
	if r.Err != nil {
		panic(r.Err)
	}
	if this.Markets == nil {

		r1 := <-this.LoadMarketsAsync()
		if r1.Err != nil {
			panic(r1.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	r2 := <-this.LoadAccountIdAsync(params)
	if r2.Err != nil {
		panic(r2.Err)
	}
	accountIdqueryVariable := r2.Value
	accountId := GetValue(accountIdqueryVariable, 0)
	query := GetValue(accountIdqueryVariable, 1)
	var request map[string]any = map[string]any{
		"accountId": accountId,
		"conid":     market["id"],
	}

	responseRecv := <-this.WebapiGetV1ApiPortfolioAccountIdPositionConid(this.Extend(request, query))
	if responseRecv.Err != nil {
		panic(responseRecv.Err)
	}
	var response []any = responseRecv.Value
	//
	//     [
	//         {
	//             "acctId": "U1234567",
	//             "conid": 265598,
	//             "contractDesc": "AAPL",
	//             "position": 614.2639,
	//             "mktPrice": 197.7639923,
	//             "mktValue": 121479.28,
	//             "currency": "USD",
	//             "avgCost": 192.7477563,
	//             "avgPrice": 192.7477563,
	//             "realizedPnl": 0.0,
	//             "unrealizedPnl": 3081.29,
	//             "assetClass": "STK",
	//             "model": ""
	//         }
	//     ]
	//
	var positions []any
	if response != nil {
		positions = ArrayTyped(response)
	} else {
		positions = []any{}
	}
	var result []any = []any{}
	for i := 0; i < len(positions); i++ {
		var position map[string]any = PositionToMap(this.ParsePosition(DerefScalar(positions[i]), market))
		if Precise.StringGt(this.SafeString(position, "contracts", "0"), "0") {
			result = append(result, position)
		}
	}

	ch <- AsyncResult[[]Position]{Value: PositionsFromList(result)}
	return nil
}
func (this *Interactivebrokers) ParsePosition(position any, optionalArgs ...any) Position {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(position, "conid")
	var resolved map[string]any = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeTimestamp(position, "timestamp")
	var contracts *string = this.SafeString(position, "position")
	var side *string = nil
	if Precise.StringGt(contracts, "0") {
		sideStr := "long"
		side = &sideStr
	} else if Precise.StringLt(contracts, "0") {
		sideStr2 := "short"
		side = &sideStr2
	}
	return this.SafePosition(map[string]any{
		"info":                        position,
		"id":                          nil,
		"symbol":                      resolved["symbol"],
		"timestamp":                   timestamp,
		"datetime":                    this.Iso8601(timestamp),
		"isolated":                    nil,
		"hedged":                      nil,
		"side":                        side,
		"contracts":                   this.ParseNumber(Precise.StringAbs(contracts)),
		"contractSize":                this.SafeNumber(resolved, "contractSize"),
		"entryPrice":                  this.SafeNumber2(position, "avgPrice", "avgCost"),
		"markPrice":                   this.SafeNumber2(position, "marketPrice", "mktPrice"),
		"notional":                    this.SafeNumber2(position, "marketValue", "mktValue"),
		"leverage":                    nil,
		"collateral":                  nil,
		"initialMargin":               nil,
		"maintenanceMargin":           nil,
		"initialMarginPercentage":     nil,
		"maintenanceMarginPercentage": nil,
		"unrealizedPnl":               this.SafeNumber(position, "unrealizedPnl"),
		"realizedPnl":                 this.SafeNumber(position, "realizedPnl"),
		"liquidationPrice":            nil,
		"marginMode":                  nil,
		"marginRatio":                 nil,
		"percentage":                  nil,
		"stopLossPrice":               nil,
		"takeProfitPrice":             nil,
		"lastUpdateTimestamp":         nil,
	})
}
func (this *Interactivebrokers) IbkrEncrypt(value any) string {
	// RFC 3986 percent-encoding (also escapes !'()*), as required by the oauth 1.0a signature base string
	var encoded string = this.Urlencode(map[string]any{
		"v": value,
	})
	return encoded[2:] // strip the 'v=' prefix
}
func (this *Interactivebrokers) IbkrBaseString(method string, url any, params map[string]any, optionalArgs ...any) string {
	var prepend string = GetArgString(optionalArgs, 0, "")
	_ = prepend
	var query string = this.Rawencode(this.Keysort(params))
	return prepend + method + "&" + this.IbkrEncrypt(url) + "&" + this.IbkrEncrypt(query)
}
func (this *Interactivebrokers) IbkrAuthHeader(params map[string]any) any {
	var sorted map[string]any = this.Keysort(params)
	var keys []string = nil
	if sorted != nil {
		keys = make([]string, 0, len(sorted))
		for objectKey := range sorted {
			keys = append(keys, objectKey)
		}
	}
	var parts []any = []any{}
	for i := 0; i < len(keys); i++ {
		var key string = keys[i]
		parts = append(parts, Add(Add(key+"=\"", sorted[key]), "\""))
	}
	return Add(Add(Add("OAuth realm=\"", this.Options["realm"]), "\", "), Join(parts, ", "))
}
func (this *Interactivebrokers) IbkrOauthBase(consumerKey any, consumerAccessToken any) map[string]any {
	return map[string]any{
		"oauth_consumer_key": consumerKey,
		"oauth_nonce":        this.RandomBytes(16),
		"oauth_timestamp":    strconv.FormatInt(this.Seconds(), 10),
		"oauth_token":        consumerAccessToken,
	}
}

/**
 * @method
 * @name interactivebrokers#ibkrImplodePath
 * @description replaces the ':name' path parameters of the webapi endpoints with the matching values of params
 * @ignore
 * @param {string} path the endpoint path, e.g. 'v1/api/iserver/account/:accountId/orders'
 * @param {object} params the request params, the path params are read from here
 * @returns {Array} the imploded path, e.g. 'v1/api/iserver/account/U1234567/orders', and the names of the path params
 */
func (this *Interactivebrokers) IbkrImplodePath(path string, params any) []any {
	var segments []string = strings.Split(path, "/")
	var pathParams []any = []any{}
	for i := 0; i < len(segments); i++ {
		var segment string = segments[i]
		if strings.HasPrefix(segment, ":") {
			var name string = segment[1:]
			pathParams = append(pathParams, name)
			AddElementToObject(segments, i, this.SafeString(params, name, segment))
		}
	}
	return []any{strings.Join(segments, "/"), pathParams}
}

/**
 * @method
 * @name interactivebrokers#ibkrGatewayBaseUrl
 * @description maps an api.ibkr.com base url to the client portal gateway url, e.g. 'https://api.ibkr.com/v1/api/' -> 'https://localhost:5000/v1/api/'
 * @ignore
 * @param {string} baseUrl the configured api url
 * @param {string} gatewayUrl options.gatewayUrl
 * @returns {string} the gateway base url
 */
func (this *Interactivebrokers) IbkrGatewayBaseUrl(baseUrl any, gatewayUrl *string) any {
	var gateway *string = gatewayUrl
	if !strings.HasSuffix(*gateway, "/") {
		gatewayStr := *gateway + "/"
		gateway = &gatewayStr
	}
	var prefix string = "https://api.ibkr.com/"
	if StartsWith(baseUrl, prefix) {
		var path string = Replace(baseUrl, prefix, "")
		return *gateway + path
	}
	return baseUrl
}

/**
 * @method
 * @name interactivebrokers#ibkrCheckOauthCredentials
 * @description throws an AuthenticationError when the oauth 1.0a credentials (apiKey, secret and options.consumer_key) are missing, requiredCredentials can not be used for this, because the client portal gateway mode needs no credentials
 * @ignore
 * @returns {boolean} true if the oauth credentials are set
 */
func (this *Interactivebrokers) IbkrCheckOauthCredentials() bool {
	if this.ApiKey == "" {
		panic(AuthenticationError(this.Id + " requires \"apiKey\" credential (the oauth access token), or set options[\"useGateway\"] to use the client portal gateway"))
	}
	if this.Secret == "" {
		panic(AuthenticationError(this.Id + " requires \"secret\" credential (the encrypted oauth access token secret), or set options[\"useGateway\"] to use the client portal gateway"))
	}
	var consumerKey *string = this.SafeString(this.Options, "consumer_key")
	if (consumerKey == nil) || (consumerKey != nil && *consumerKey == "") {
		panic(AuthenticationError(this.Id + " requires options[\"consumer_key\"] (the oauth consumer key), or set options[\"useGateway\"] to use the client portal gateway"))
	}
	return true
}

/**
 * @method
 * @name interactivebrokers#ibkrIsGatewayRequest
 * @description tells whether a request is routed to the client portal gateway instead of the oauth api
 * @ignore
 * @param {string} path the endpoint path
 * @returns {boolean} true if the request is sent to the client portal gateway
 */
func (this *Interactivebrokers) IbkrIsGatewayRequest(path any) bool {
	// with the client portal gateway signIn () never sets a live session token, so besides options.useGateway
	// the requests are routed to the gateway when there is no live session token and oauth is not configured
	// (e.g. public calls like fetchOpenInterests made before any private call)
	var useGatewayOption *bool = this.SafeBool(this.Options, "useGateway", false)
	var hasLiveSessionToken bool = (this.SafeString(this.Options, "liveSessionToken") != nil)
	var oauthConfigured bool = (this.SafeString(this.Options, "encryptionPemPath") != nil) && (this.SafeString(this.Options, "dhParamPemPath") != nil)
	var isLiveSessionTokenRequest bool = EndsWith(path, "v1/api/oauth/live_session_token")
	return (useGatewayOption != nil && *useGatewayOption) || (!hasLiveSessionToken && !oauthConfigured && !isLiveSessionTokenRequest)
}
func (this *Interactivebrokers) Sign(path string, optionalArgs ...any) map[string]any {
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	implodedPathpathParamsVariable := this.IbkrImplodePath(path, params)
	implodedPath := GetValue(implodedPathpathParamsVariable, 0)
	pathParams := GetValue(implodedPathpathParamsVariable, 1)
	var apiBase string = api[0]
	var baseUrl any = Add(this.UrlsApi[apiBase], implodedPath)
	var url any = baseUrl
	var query any = this.Omit(params, pathParams)
	queryMap, _ := query.(map[string]any)
	var hasQuery bool = (len(queryMap) > 0)
	var isGetOrDelete bool = (method == "GET") || (method == "DELETE")
	var requestBody any = nil
	var requestHeaders map[string]any = nil
	var isLiveSessionTokenRequest bool = strings.HasSuffix(path, "v1/api/oauth/live_session_token")
	if this.IbkrIsGatewayRequest(path) {
		// the client portal gateway holds the authenticated session, requests are sent unsigned
		var gatewayUrl *string = this.SafeString(this.Options, "gatewayUrl")
		url = Add(this.IbkrGatewayBaseUrl(this.UrlsApi[apiBase], gatewayUrl), implodedPath)
		if isGetOrDelete {
			if hasQuery {
				url = Add(url, "?"+this.Urlencode(query))
			}
		} else {
			// the gateway rejects bodiless POST/PUT requests with http 411 (Length Required)
			if hasQuery {
				requestBody = this.Json(query)
			} else {
				requestBody = "{}"
			}
		}
		requestHeaders = map[string]any{
			"Content-Type": "application/json",
			"User-Agent":   "ccxt",
		}
		return map[string]any{
			"url":     url,
			"method":  method,
			"body":    requestBody,
			"headers": requestHeaders,
		}
	}
	this.IbkrCheckOauthCredentials()
	var oauthParams map[string]any = this.IbkrOauthBase(this.Options["consumer_key"], this.ApiKey)
	if isLiveSessionTokenRequest {
		// the live session token request is signed with RSA-SHA256,
		// its parameters (diffie_hellman_challenge) are sent as oauth parameters in the Authorization header
		var accessTokenSecretHex *string = this.SafeString(this.Options, "accessTokenSecretHex", "")
		var signatureKey any = this.ReadFile(this.Options["signaturePemPath"])
		oauthParams["oauth_signature_method"] = "RSA-SHA256"
		var authParams map[string]any = this.Extend(oauthParams, query)
		var auth string = this.IbkrBaseString(method, baseUrl, authParams, accessTokenSecretHex)
		var signature string = Rsa(auth, signatureKey, sha256)
		authParams["oauth_signature"] = this.IbkrEncrypt(signature)
		requestHeaders = map[string]any{
			"Authorization": this.IbkrAuthHeader(authParams),
			"User-Agent":    "ccxt",
		}
	} else {
		// private requests are signed with HMAC-SHA256 using the live session token obtained by signIn ()
		var liveSessionToken *string = this.SafeString(this.Options, "liveSessionToken")
		if liveSessionToken == nil {
			panic(AuthenticationError(this.Id + " requires a live session token, call signIn() first (or set options.useGateway = true to use the client portal gateway)"))
		}
		oauthParams["oauth_signature_method"] = "HMAC-SHA256"
		var signingParams map[string]any = oauthParams
		if isGetOrDelete {
			if hasQuery {
				url = Add(url, "?"+this.Urlencode(query))
				// the query-string params are part of the signature base string too
				signingParams = this.Extend(oauthParams, query)
			}
		} else if hasQuery {
			requestBody = this.Json(query)
		}
		var auth string = this.IbkrBaseString(method, baseUrl, signingParams)
		var signature string = this.Hmac(this.Encode(auth), this.Base64ToBinary(liveSessionToken), sha256, "base64")
		oauthParams["oauth_signature"] = this.IbkrEncrypt(signature)
		requestHeaders = map[string]any{
			"Authorization": this.IbkrAuthHeader(oauthParams),
			"Content-Type":  "application/json",
			"User-Agent":    "ccxt",
		}
	}
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    requestBody,
		"headers": requestHeaders,
	}
}

/**
 * @method
 * @name interactivebrokers#ibkrIsAuthRequest
 * @description tells whether the endpoint is used by signIn () itself, so it must not trigger authenticate ()
 * @ignore
 * @param {string} path the endpoint path
 * @returns {boolean} true for the session/authentication endpoints
 */
func (this *Interactivebrokers) IbkrIsAuthRequest(path any) bool {
	var authPaths []string = []string{"v1/api/oauth/live_session_token", "v1/api/oauth/request_token", "v1/api/oauth/access_token", "v1/api/iserver/auth/status", "v1/api/iserver/auth/ssodh/init", "v1/api/iserver/accounts", "v1/api/tickle", "v1/api/logout"}
	return this.InArray(path, authPaths)
}
func (this *Interactivebrokers) RequestAsync(path any, optionalArgs ...any) <-chan AsyncResult[any] {
	ch := make(chan AsyncResult[any], 1)
	go this.requestBody(ch, path, optionalArgs...)
	return ch
}
func (this *Interactivebrokers) requestBody(ch chan AsyncResult[any], path any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	chSent := false
	_ = chSent
	// every non-auth call renews an expired live session token (or re-checks the gateway session) first,
	// so methods that do not call authenticate () themselves never send a stale token
	var api []string = GetArgStringSlice(optionalArgs, 0, []string{"public"})
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	var config map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = config
	if !this.IbkrIsAuthRequest(path) && !(*this.SafeBool(this.Options, "signInInProgress", false)) {

		r := <-this.AuthenticateAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	// right after a new brokerage session is opened, IBKR may still reject trading endpoints with
	// {"error":"Please query /accounts first"} even though iserver/accounts was already called,
	// so iserver/accounts is queried again and the request is retried
	if this.IbkrIsGatewayRequest(path) && (this.ValidateServerSsl != false) {
		// the gateway serves a self-signed certificate, so its validation is disabled, only in gateway mode (oauth requests to api.ibkr.com are always verified)
		// done here instead of sign (), which cannot change the instance in the statically typed ports
		this.SetValidateServerSsl(false)
	}
	var isAccountsPath bool = (IsEqual(path, "iserver/accounts")) || (IsEqual(path, "v1/api/iserver/accounts"))
	var options, _ = this.Options["queryAccountsFirst"].(map[string]any)
	var retries int64 = *this.SafeInteger(options, "retries", 3)
	var retryDelay *int64 = this.SafeInteger(options, "retryDelay", 1000)
	for i := 0; int64(i) <= retries; i++ {

		{
			func(this *Interactivebrokers) (ret_ any) {
				defer func() {
					if e := recover(); e != nil {
						if e == "break" {
							return
						}
						ret_ = func(this *Interactivebrokers) any {
							// catch block:
							var message string = this.ExceptionMessage(e, false)
							var mustQueryAccounts bool = (strings.Index(message, "query /accounts first") >= 0)
							if isAccountsPath || !mustQueryAccounts || (IsEqual(i, retries)) {
								panic(e)
							}
							this.Options["serviceAccountsLoaded"] = false

							r1 := <-this.WebapiGetV1ApiIserverAccounts()
							if r1.Err != nil {
								panic(r1.Err)
							}
							this.Options["serviceAccountsLoaded"] = true

							<-this.Sleep(retryDelay)
							return nil
						}(this)
					}
				}()
				// try block:

				r2 := <-this.Fetch2Async(path, api, method, params, config)
				if r2.Err != nil {
					panic(r2.Err)
				}
				ch <- AsyncResult[any]{Value: r2.Value}
				chSent = true
				return nil

			}(this)
			if chSent {
				return nil
			}

		}
	}

	return nil
}
func (this *Interactivebrokers) HandleErrors(code int64, reason string, url string, method string, headers any, body string, response any, requestHeaders any, requestBody any) any {
	if (code == 401) && (*this.SafeBool(this.Options, "useGateway", false)) {
		// the gateway answers every request with 401 once its sso login is lost (daily reset, container restart, competing login)
		this.Options["gatewayAuthenticatedTimestamp"] = nil
		var gatewayUrl *string = this.SafeString(this.Options, "gatewayUrl")
		panic(AuthenticationError(this.Id + " the client portal gateway is not logged in, log in again at " + *gatewayUrl + " in a browser. Current action: " + method + " " + url + " " + body))
	}
	if response == nil {
		return nil // fallback to default error handler
	}
	//
	//     {
	//         "error": "Bad Request: Conid(s) missing",
	//         "statusCode": 400
	//     }
	//
	var errorMessage *string = this.SafeString(response, "error")
	if errorMessage != nil {
		var feedback string = this.Id + " " + body
		var statusCode *string = this.SafeString(response, "statusCode")
		this.ThrowExactlyMatchedException(this.Exceptions["exact"], statusCode, feedback)
		this.ThrowBroadlyMatchedException(this.Exceptions["broad"], errorMessage, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewInteractivebrokers(userConfig map[string]any) *Interactivebrokers {
	p := newInteractivebrokers()
	p.Init(userConfig)
	return p
}

func (this *Interactivebrokers) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe(), this)
}

